{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    min_sum = sum(s['minimum'] for s in segments)
    cap_sum = sum(s['capacity'] for s in segments)
    if budget < min_sum or budget > cap_sum:
        raise ValueError(f"Budget {budget} out of range [{min_sum}, {cap_sum}]")
    allocs = [s['minimum'] for s in segments]
    remaining = budget - min_sum
    while remaining > 0:
        best_idx = -1
        best_ratio = -1.0
        for i, s in enumerate(segments):
            if allocs[i] >= s['capacity']:
                continue
            ratio = s['importance'] / (allocs[i] + 1.0)
            if ratio > best_ratio:
                best_ratio = ratio
                best_idx = i
        if best_idx == -1:
            raise ValueError("Cannot allocate remaining tokens (should not happen)")
        allocs[best_idx] += 1
        remaining -= 1
    by_name = {s['name']: alloc for s, alloc in zip(segments, allocs)}
    total = sum(allocs)
    return {"allocations": allocs, "by_name": by_name, "total": total}"
}
